export function comprobar(){const archivos=['g42.mjs','lib/g42_core.mjs','lib/contrato.mjs','G42.postman_collection.json','pruebas/newman_hijo.mjs','pruebas/registro_qa.mjs','pruebas/g42_local.test.mjs','pruebas/g42_escenarios.test.mjs','pruebas/g42_dto.test.py','pruebas/contrato_g42.json','preparacion_ORD-G42-001.md','README.md'];const faltan=archivos.filter(x=>!fs.existsSync(path.join(DIR,x)));const col=JSON.parse(fs.readFileSync(COL,'utf8'));const ok=!faltan.length&&col.item.length===8&&(!fs.existsSync(path.join(DIR,'Resultados'))||!fs.readdirSync(path.join(DIR,'Resultados')).some(x=>x.endsWith('.md')))&&col.item.every(x=>x.request.method==='GET'&&x.request.header.some(h=>h.key==='Authorization'))&&contrato.rutas.every(x=>x.cita?.startsWith('src/')||x.ruta==='/test-control/runs/{id}');console.log(JSON.stringify({grupo:'G42',ok,faltan,items:col.item.length,newman:versionNewman(),sha256:Object.fromEntries(archivos.filter(x=>fs.existsSync(path.join(DIR,x))).map(x=>[x,hash(path.join(DIR,x))]))}));return ok?0:2;}
export function contexto(argv,ensayo=false){const v=k=>argv.includes(k)?argv[argv.indexOf(k)+1]:null;const op=v('--operacion'),version=Number(v('--version')),intento=Number(v('--intento')),runId=v('--run-id'),ref=v('--autorizacion'),archivo=path.resolve(v('--contexto')??'.');if(!CAPACIDADES.operaciones.includes(op)||!Number.isInteger(version)||version<1||!Number.isInteger(intento)||intento<1||!ref||!new RegExp(`^RUN-G42-V${version}-\\d{8}-\\d{6}$`).test(runId??''))throw Error('CONTEXTO_INCOMPLETO');const dir=ensayo?path.dirname(archivo):path.join(DIR,...(version===1?['Resultados',runId]:[`EvaluacionV${version}`,'Resultados',runId]));if(ensayo&&(path.basename(dir)!==runId||!dir.startsWith(path.resolve(os.tmpdir())+path.sep)))throw Error('ENSAYO_FUERA_TEMPORAL');if(path.dirname(archivo)!==dir||path.basename(archivo)!=='contexto_operacion.json')throw Error('CONTEXTO_FUERA_RUN');const c=JSON.parse(fs.readFileSync(archivo,'utf8'));if(c.grupo!=='G42'||c.run_id!==runId||c.version!==version||c.intento!==intento||c.operacion!==op.toUpperCase()||c.referencia!==ref||JSON.stringify(c.casos)!==JSON.stringify(CASOS)||version!==2||!['reevaluar','reintentar'].includes(op)||JSON.stringify(c.alcance_reevaluacion?.casos)!==JSON.stringify(CASOS)||(c.alcance?.casos&&JSON.stringify(c.alcance.casos)!==JSON.stringify(CASOS))||(op==='reevaluar'&&c.version_anterior!==1))throw Error('CONTEXTO_INCOHERENTE');return{operacion:op,version,intento,runId,referencia:ref,dir,ensayo};}
export function leerEnv(proceso=process.env,archivo=path.join(ROOT,'.env.qa')){const e={};if(proceso===process.env&&proceso.G42_ENSAYO_LOCAL!=='SI'&&proceso.QA_AUTORIZADO==='SI'&&fs.existsSync(archivo))for(const line of fs.readFileSync(archivo,'utf8').split(/\r?\n/)){const m=line.match(/^\s*([A-Z][A-Z0-9_]*)\s*=(.*)$/);if(m)e[m[1]]=m[2].trim().replace(/^(['"])(.*)\1$/,'$2');}Object.assign(e,proceso);e.QA_AUTORIZADO=proceso.QA_AUTORIZADO;return e;}
export function preflight(c,e){const barreras=['SIGAB_API_TEST_BASE','QA_SANDBOX_SECRET','QA_CONTADOR_EMAIL','QA_CONTADOR_PASSWORD','QA_ADMIN_EMAIL','QA_ADMIN_PASSWORD'].filter(k=>!String(e[k]??'').trim());if(e.QA_AUTORIZADO!=='SI')barreras.push('QA_AUTORIZADO');const base=String(e.SIGAB_API_TEST_BASE??'').replace(/\/+$/,'');if(c.ensayo?!/^http:\/\/(127\.0\.0\.1|localhost):\d+$/.test(base):base!==API)barreras.push('API_NO_CANONICA');if(!versionNewman())barreras.push('NEWMAN_NO_DISPONIBLE');return{grupo:'G42',run_id:c.runId,ok:!barreras.length,barreras,presupuesto:LIMITE,herramientas:{node:process.version,newman:versionNewman()},efectos_externos:['Alertas de precios y avisos de cierre pueden persistir fuera del sandbox','Procesamiento de eventos M02 pendientes']};}
