export const conPeticiones=(fetcher,fn,fechaEnsayo=null)=>local.run({fetcher,ocupado:false,hijo:false,solicitudes:0,fechaEnsayo},fn);
async function enviar(r,c,e,t,actor,metodo,ruta,cuerpo,binario=false,sinContrato=false){validarRuta(ruta);const state=local.getStore();if(state.ocupado||state.hijo)throw Error('PETICION_CONCURRENTE');if(state.solicitudes>=LIMITE.solicitudes_totales||Date.now()>r.deadline)throw Error('PRESUPUESTO_AGOTADO');const def=esquema(metodo,ruta);if(!def&&!(metodo==='PUT'||metodo==='DELETE')||!def&&metodo==='DELETE'&&!ruta.startsWith('/finanzas/periodos/'))throw Error(`RUTA_FUERA_CONTRATO_${metodo}_${ruta}`);const row={id:`G42-${String(r.solicitudes.length+1).padStart(3,'0')}`,metodo,ruta:ruta.split('?')[0],actor,http:null};r.solicitudes.push(row);if(!['GET'].includes(metodo)&&!ruta.startsWith('/test-control/'))r.escrituras.push(row.id);state.ocupado=true;state.solicitudes++;try{const base=e.SIGAB_API_TEST_BASE.replace(/\/+$/,'');const headers=actor==='anon'?{}:{Authorization:`Bearer ${t[actor]}`,...(r.sandboxCerrado?{}:{'X-Test-Run-Id':c.runId,'X-Sandbox-Secret':t.secret}),...(cuerpo===undefined?{}:{'Content-Type':'application/json'})};const z=await state.fetcher(base+ruta,{method:metodo,redirect:'manual',headers,...(cuerpo===undefined?{}:{body:JSON.stringify(cuerpo)}),signal:AbortSignal.timeout(120000)});row.http=z.status;let data;if(binario&&z.status<400){const bytes=Buffer.from(await z.arrayBuffer());data={bytes,tipo:z.headers.get('content-type')??''};}else{try{data=await z.json();}catch{data=null;}}if(z.status>=200&&z.status<300&&!binario&&def&&!sinContrato){const original=data;const extras=new Set();const comprobada=validarLecturas(data,metodo,ruta,{estricto:c.ensayo,camposExtra:extras});r.campos_extra_observados.push(...[...extras].map(campo=>({ruta:ruta.split('?')[0],campo})));if(metodo==='GET')data=comprobada;if(/^\/finanzas\/estados-resultados\/\d+$/.test(ruta)||/^\/finanzas\/periodos\/\d+\/estados-resultados/.test(ruta))data=original;r.contraste_contrato.push({ruta:ruta.split('?')[0],http:200,resultado:'coincide'});}if(z.status>=400){const coincide=validarError(data);r.contraste_contrato.push({ruta:ruta.split('?')[0],http:z.status,resultado:coincide?'coincide':'difiere',esquema:'error_respuesta'});row.error=clean(data?.error_code??data?.message??z.status);}return{http:z.status,data,headers:z.headers};}finally{state.ocupado=false;}}
const g=async(r,c,e,t,ruta,actor='contador')=>{const z=await enviar(r,c,e,t,actor,'GET',ruta);if(z.http!==200)throw Error(`GET_${z.http}_${ruta}`);return z.data;};
async function login(r,c,e,actor){const email=e[`QA_${actor.toUpperCase()}_EMAIL`],password=e[`QA_${actor.toUpperCase()}_PASSWORD`];const state=local.getStore();if(state.ocupado)throw Error('PETICION_CONCURRENTE');state.ocupado=true;state.solicitudes++;const row={id:`G42-${String(r.solicitudes.length+1).padStart(3,'0')}`,metodo:'POST',ruta:'/sesiones/',actor,http:null};r.solicitudes.push(row);try{const z=await state.fetcher(e.SIGAB_API_TEST_BASE+'/sesiones/',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({correo_electronico:email,contrasena:password}),signal:AbortSignal.timeout(120000)});row.http=z.status;if(z.status===200){const extras=new Set(),dato=validarLecturas(await z.json(),'POST','/sesiones/',{estricto:c.ensayo,camposExtra:extras});r.campos_extra_observados.push(...[...extras].map(campo=>({ruta:'/sesiones/',campo})));return dato.token;}if(z.status>=400){let data;try{data=await z.json();}catch{data=null;}const coincide=validarError(data);r.contraste_contrato.push({ruta:'/sesiones/',http:z.status,resultado:coincide?'coincide':'difiere',esquema:'error_respuesta'});row.error=clean(data?.error_code??data?.message??z.status);}return null;}finally{state.ocupado=false;}}
