async function bandejaCompleta(r,c,e,t){let items=[],pagina=1,total=0;do{const x=await g(r,c,e,t,`/notificaciones?pagina=${pagina}&tamano=50`);if(!Array.isArray(x.items)||!Number.isInteger(x.total)||x.total<0)throw Error('BANDEJA_INCOMPLETA');items.push(...x.items);total=x.total;if(pagina++>20||items.length>total)throw Error('BANDEJA_PAGINACION');}while(items.length<total);return items;}
async function asignarMatriz(r,c,e,t,cfg){const necesarios=[['VARIACION_VR_TB','PERDIDA'],['VARIACION_VR_PM','GANANCIA'],['DEPRECIACION_ACTIVO_COSTO','UNICO'],['MANO_OBRA_PROPIA','UNICO'],['CONSUMO_INSUMO','UNICO']];for(const [tipo_hecho,sentido] of necesarios){if(cfg.matriz.some(x=>x.tipo_hecho===tipo_hecho&&x.sentido===sentido&&x.id_especie==null&&x.subtipo_costo==null))continue;const origen=cfg.matriz.find(x=>x.sentido===sentido&&x.id_especie==null&&x.subtipo_costo==null&&x.cuenta_debito&&x.cuenta_credito);if(!origen)throw Error(`MATRIZ_SIN_PAR_${tipo_hecho}_${sentido}`);const cuerpo={tipo_hecho,sentido,id_especie:null,subtipo_costo:null,cuenta_debito:origen.cuenta_debito,cuenta_credito:origen.cuenta_credito};const z=await enviar(r,c,e,t,'contador','POST','/finanzas/configuracion/matriz',cuerpo);if(z.http!==201)throw Error(`MATRIZ_POST_${z.http}`);r.nuevasAsignaciones.push(z.data.id_asignacion_cuenta_contable);}}
async function resolverPendientes241(r,c,e,t,cfg,lineas){
  const atendidas=new Set();
  for(const ln of lineas.filter(x=>x.estado==='PENDIENTE_CUENTA')){
    const tipo_hecho=ln.tipo_hecho_corregido??ln.tipo_hecho,sentido=ln.sentido,id_especie=ln.id_especie,subtipo_costo=ln.subtipo_costo??null;
    if(!tipo_hecho||!sentido||!id_especie)throw Error('PENDIENTE_241_SIN_COMBINACION');
    const clave=JSON.stringify([tipo_hecho,sentido,Number(id_especie),subtipo_costo]);
    if(atendidas.has(clave))continue;
    atendidas.add(clave);
    const candidatas=cfg.matriz.filter(x=>x.tipo_hecho===tipo_hecho&&x.sentido===sentido&&x.cuenta_debito&&x.cuenta_credito&&(x.id_especie==null||Number(x.id_especie)===Number(id_especie))&&(x.subtipo_costo==null||x.subtipo_costo===subtipo_costo));
    const especifica=candidatas.find(x=>Number(x.id_especie)===Number(id_especie)&&x.subtipo_costo===subtipo_costo)??candidatas.find(x=>Number(x.id_especie)===Number(id_especie));
    const generica=candidatas.find(x=>x.id_especie==null&&x.subtipo_costo===subtipo_costo)??candidatas.find(x=>x.id_especie==null);
    const origen=especifica??generica??cfg.matriz.find(x=>x.tipo_hecho===tipo_hecho&&x.sentido===sentido&&x.subtipo_costo===subtipo_costo&&x.cuenta_debito&&x.cuenta_credito&&Number(x.id_especie)!==Number(id_especie));
    if(!origen)throw Error(`PENDIENTE_241_SIN_PAR_${tipo_hecho}_${sentido}`);
    const cuerpo={tipo_hecho,sentido,id_especie,subtipo_costo:especifica||generica?origen.subtipo_costo:subtipo_costo,cuenta_debito:origen.cuenta_debito,cuenta_credito:origen.cuenta_credito};
    const z=await enviar(r,c,e,t,'contador','POST','/finanzas/configuracion/matriz',cuerpo);
    const diagnostico={linea:ln.id_linea_asiento_nic41,cobertura:especifica?'ESPECIFICA':generica?'GENERICA':'OTRA_ESPECIE',asignacion_origen:origen.id_asignacion_cuenta_contable,cuentas_iguales:true,http:z.http,asignacion:z.data?.id_asignacion_cuenta_contable??null,lineas_resueltas:z.data?.lineas_resueltas??null};
    r.diagnostico_preflight.resolucion_241??=[];r.diagnostico_preflight.resolucion_241.push(diagnostico);
    if(z.http!==201)throw Error(`PENDIENTE_241_POST_${z.http}`);
    r.nuevasAsignaciones.push(z.data.id_asignacion_cuenta_contable);
    if(!Number.isInteger(z.data.lineas_resueltas)||z.data.lineas_resueltas<1)continue;
    r.pendientes_resueltos.push(diagnostico);
  }
}
function precioPropuesto(base,umbral,direccion){const b=Number(base),u=Number(umbral);if(!Number.isFinite(b)||b<=0||!Number.isFinite(u)||u<=0)throw Error('PRECIO_O_UMBRAL_INVALIDO');let n=String(Math.round(b*(1+direccion*u/400)));if(Number(n)===b)n=String(Math.round(b)+(direccion>0?1:-1));if(Number(n)<=0)throw Error('PRECIO_PROPUESTO_INVALIDO');return{precio:n,confirmar_desviacion:Math.abs(Number(n)-b)/b*100>=u};}
async function registrarPrecio(r,c,e,t,base,especie,umbral,direccion){const p=precioPropuesto(base.precio_unitario,umbral,direccion);const cuerpo={id_especie:especie,categoria:base.categoria,precio_unitario:p.precio,fecha_vigencia:hoy(),fuente:base.fuente,evidencia_documental:`QA ${c.runId} G42`,confirmar_desviacion:p.confirmar_desviacion,...(base.fuente==='ESTIMADA'?{justificacion_estimacion:`QA ${c.runId}: precio estimado para medir cierre`}:{})};const z=await enviar(r,c,e,t,'contador','POST','/finanzas/precios',cuerpo);if(z.http!==201)throw Error(`PRECIO_POST_${z.http}`);r.nuevosPrecios.push(z.data.id_precio_mercado);return{id_especie:base.id_especie,categoria:base.categoria,fuente:base.fuente,id_metrica_produccion:base.id_metrica_produccion,precio_unitario:p.precio};}
